	ids := make(map[string]struct{}, len(*req.Tasks))
	priorities := make(map[int64]struct{}, len(*req.Tasks))
	for i := range *req.Tasks {
		in := (*req.Tasks)[i]
		if !validTaskID(in.ID) {
			return nil, false
		}
		if _, dup := ids[in.ID]; dup {
			return nil, false
		}
		ids[in.ID] = struct{}{}
		if in.Priority == nil || *in.Priority < 0 || *in.Priority > 255 {
			return nil, false
		}
		if _, dup := priorities[*in.Priority]; dup {
			return nil, false
		}
		priorities[*in.Priority] = struct{}{}
		if in.Execution == nil || *in.Execution <= 0 || *in.Execution > maxPeriodicValue {
			return nil, false
		}
		if in.Period == nil || *in.Period <= 0 || *in.Period > maxPeriodicValue {
			return nil, false
		}
		if in.Deadline == nil || *in.Deadline <= 0 || *in.Deadline > maxPeriodicValue ||
			*in.Deadline > *in.Period {
			return nil, false
		}
		tasks = append(tasks, periodicTask{
			id:        in.ID,
			priority:  *in.Priority,
			execution: *in.Execution,
			period:    *in.Period,
			deadline:  *in.Deadline,
		})
	}
	return tasks, true
}

// analyzePeriodic computes worst-case response times under synchronous
// release, fixed priorities, preemptive scheduling, no blocking and no
// release jitter (constrained deadlines: deadline <= period).
func analyzePeriodic(tasks []periodicTask) periodicResponse {
	resp := periodicResponse{
		Schedulable: true,
		Results:     make([]periodicTaskResult, len(tasks)),
	}
	for i, t := range tasks {
		rt := worstResponseTime(tasks, i)
		result := periodicTaskResult{ID: t.id, ResponseTime: rt}
		if rt != nil && *rt <= t.deadline {
			result.DeadlineStatus = "met"
		} else {
			result.DeadlineStatus = "missed"
			resp.Schedulable = false
		}
		resp.Results[i] = result
	}
	return resp
}

// interference sums ceil(w/period)*execution over every strictly
// higher-priority task. A result of false means the sum exceeds int64.
func interference(tasks []periodicTask, idx int, w int64) (int64, bool) {
	t := tasks[idx]
	var sum int64
	for j := range tasks {
		hp := tasks[j]
		if hp.priority >= t.priority {
			continue
		}
		jobs := (w + hp.period - 1) / hp.period
		term, ok := saturatingMul(jobs, hp.execution)
		if !ok {
			return 0, false
		}
		sum, ok = saturatingAdd(sum, term)
		if !ok {
			return 0, false
		}
	}
	return sum, true
}

// worstResponseTime returns the least fixed point of
//
//	w = C_i + sum_{j: prio(j) < prio(i)} ceil(w/T_j) * C_j
//
// starting from w0 = C_i, or nil if it does not settle at or before the
// deadline. Because the interference term is a non-decreasing step function
// f, the iteration is monotone and its least fixed point is at most the
// deadline exactly when C_i + f(deadline) <= deadline; that single check
// decides a miss (including an initial execution time past the deadline and
// any int64 overflow) without walking a potentially long diverging sequence.
func worstResponseTime(tasks []periodicTask, idx int) *int64 {
	t := tasks[idx]
	if t.execution > t.deadline {
		return nil
	}
	atDeadline, ok := interference(tasks, idx, t.deadline)
	if !ok {
		return nil
	}
	busy, ok := saturatingAdd(t.execution, atDeadline)
	if !ok || busy > t.deadline {
		return nil
	}

	w := t.execution
	for {
		f, ok := interference(tasks, idx, w)
		if !ok {
			return nil
		}
		next, ok := saturatingAdd(t.execution, f)
		if !ok || next > t.deadline {
			return nil
		}
		if next <= w {
			// Monotonicity makes equality the only settled case.
			rt := w
			return &rt
		}
		w = next
	}
}

func saturatingAdd(a, b int64) (int64, bool) {
	if b > maxInt64-a {
		return 0, false
	}
	return a + b, true
}

func saturatingMul(a, b int64) (int64, bool) {
	if a == 0 || b == 0 {
		return 0, true
	}
	if a > maxInt64/b {
		return 0, false
	}
	return a * b, true
}

