// TestWorstResponseTimeDifferential compares the deadline-bounded fixed-point
// computation against a direct iteration of the RTA recurrence on random
// small task sets.
func TestWorstResponseTimeDifferential(t *testing.T) {
	seed := rand.New(rand.NewSource(0x5eed))
	for iter := 0; iter < 5000; iter++ {
		n := 1 + seed.Intn(6)
		tasks := make([]periodicTask, n)
		prios := seed.Perm(n)
		ids := map[string]bool{}
		for i := 0; i < n; i++ {
			id := "t" + strconv.Itoa(i)
			ids[id] = true
			c := int64(1 + seed.Intn(5))
			tp := int64(c + seed.Intn(20))
			d := int64(c + seed.Intn(int(tp-c+1)))
			tasks[i] = periodicTask{
				id:        id,
				priority:  int64(prios[i]),
				execution: c,
				period:    tp,
				deadline:  d,
			}
		}
		for i, tk := range tasks {
			got := worstResponseTime(tasks, i)

			// Reference: iterate w0=C, w_{k+1}=C+sum ceil(w/Tj)*Cj until a
			// fixed point or a value past the deadline.
			var want *int64
			w := tk.execution
			if w <= tk.deadline {
				for {
					next := tk.execution
					for j, hp := range tasks {
						if j == i || hp.priority >= tk.priority {
							continue
						}
						next += ((w + hp.period - 1) / hp.period) * hp.execution
					}
					if next == w {
						v := w
						want = &v
						break
					}
					if next > tk.deadline {
						break
					}
					w = next
				}
			}

			if (got == nil) != (want == nil) {
				t.Fatalf("iter %d task %d %+v: got %v, want %v", iter, i, tk, got, want)
			}
			if got != nil && *got != *want {
				t.Fatalf("iter %d task %d %+v: got %d, want %d", iter, i, tk, *got, *want)
			}
		}
	}
}

