// analyzePeriodic computes worst-case response times under synchronous
// release, fixed priorities, preemptive scheduling, no blocking and no
// release jitter (constrained deadlines: deadline <= period).
func analyzePeriodic(tasks []periodicTask) periodicResponse {
	n := len(tasks)
	// hp[i] lists the strictly higher-priority tasks of task i in input
	// order; oversubscribed[i] marks hp sets whose total utilization is at
	// least 1 (no finite fixed point exists for task i).
	hp := make([][]periodicTask, n)
	oversubscribed := make([]bool, n)
	for i, t := range tasks {
		var util big.Rat
		for j := range tasks {
			if tasks[j].priority < t.priority {
				hp[i] = append(hp[i], tasks[j])
				util.Add(&util, new(big.Rat).SetFrac(
					big.NewInt(tasks[j].execution), big.NewInt(tasks[j].period)))
			}
		}
		if util.Cmp(big.NewRat(1, 1)) >= 0 {
			oversubscribed[i] = true
		}
	}

	resp := periodicResponse{
		Schedulable: true,
		Results:     make([]periodicTaskResult, n),
	}
	for i, t := range tasks {
		rt := worstResponseTime(t, hp[i], oversubscribed[i])
		result := periodicTaskResult{ID: t.id, ResponseTime: rt}
		if rt != nil && *rt <= t.deadline {
			result.DeadlineStatus = "met"
		} else {
			result.DeadlineStatus = "missed"
			resp.Schedulable = false
		}
		resp.Results[i] = result
	}
	return resp
}

// interference sums ceil(w/period)*execution over every higher-priority
// task. A result of false means the sum exceeds int64.
func interference(hp []periodicTask, w int64) (int64, bool) {
	var sum int64
	for _, t := range hp {
		jobs := (w + t.period - 1) / t.period
		term, ok := saturatingMul(jobs, t.execution)
		if !ok {
			return 0, false
		}
		sum, ok = saturatingAdd(sum, term)
		if !ok {
			return 0, false
		}
	}
	return sum, true
}

// worstResponseTime returns the least fixed point of
//
//	w = C + sum_j ceil(w/T_j) * C_j   (j ranging over hp)
//
// starting from w0 = C, or nil if it does not settle at or before the
// deadline. The iteration is a strictly increasing chain of integers bounded
// by the deadline, so it either reaches equality or crosses the deadline.
//
// The iteration has no finite fixed point when the higher-priority workload
// alone saturates the processor (sum C_j/T_j >= 1): interference then keeps
// growing forever. Such a task misses its deadline immediately; exact
// rational arithmetic decides the threshold so a sum like 1/3+1/3+1/3 is not
// misclassified by floating-point rounding. With utilization strictly below
// 1 a fixed point exists, and every evaluated value is provably below
// 1e12 + 256*1e12, well inside int64; the saturating arithmetic is defense
// in depth only.
func worstResponseTime(t periodicTask, hp []periodicTask, oversubscribed bool) *int64 {
	if oversubscribed || t.execution > t.deadline {
		return nil
	}
	w := t.execution
	for {
		f, ok := interference(hp, w)
		if !ok {
			return nil
		}
		next, ok := saturatingAdd(t.execution, f)
		if !ok || next > t.deadline {
			return nil
		}
		if next == w {
			rt := w
			return &rt
		}
		w = next
	}
}

