func TestPeriodicOverflowAndLargeValuesDoNotFail(t *testing.T) {
	// High-priority interference at the deadline would reach 1e24: overflow
	// must be treated as a missed deadline, never a 5xx or wraparound.
	resp := periodicOK(t, `{"tasks":[
		{"id":"low","priority":1,"execution":1,"period":1000000000000,"deadline":1000000000000},
		{"id":"hi","priority":0,"execution":1000000000000,"period":1,"deadline":1}
	]}`)
	if resp.Schedulable {
		t.Fatalf("schedulable = true, want false")
	}
	low := resp.Results[0]
	if low.ResponseTime != nil || low.DeadlineStatus != "missed" {
		t.Fatalf("low result = %+v, want null/missed", low)
	}
	hi := resp.Results[1]
	if hi.ResponseTime == nil || *hi.ResponseTime != 1_000_000_000_000 || hi.DeadlineStatus != "met" {
		t.Fatalf("hi result = %+v", hi)
	}

	// No interference: the largest legal execution meeting the largest
	// deadline returns the boundary value itself.
	resp = periodicOK(t, `{"tasks":[
		{"id":"max","priority":0,"execution":1000000000000,"period":1000000000000,"deadline":1000000000000}
	]}`)
	mr := resp.Results[0]
	if !resp.Schedulable || mr.ResponseTime == nil || *mr.ResponseTime != 1_000_000_000_000 {
		t.Fatalf("max result = %+v", mr)
	}

	// Miss without overflow, by one unit: the deadline-bound check must not
