func roundsFor(tk periodicTask, hp []periodicTask) int {
	w := tk.execution; k := 0
	for {
		k++
		sum := int64(0)
		for _, h := range hp {
			sum += ((w+h.period-1)/h.period)*h.execution
		}
		nw := tk.execution + sum
		if nw == w || nw > tk.deadline { return k }
		w = nw
	}
}

func TestZZAdversarialRounds(t *testing.T) {
	D := int64(1_000_000_000_000)
	mk := func(hp [][2]int64) ([]periodicTask, bool) {
		var list []periodicTask
		var u big.Rat
		for p, c := range hp {
			list = append(list, periodicTask{id:"h", priority:int64(p), execution:c, period:1_000_000_000_000/1, deadline:1})
			list[p].period = 1 // placeholder overwritten
		}
		_=u
		return list, true
	}
	_ = mk

	type tc struct{
		name string
		hp []periodicTask
	}
	var cases []tc

	// 1) 255 tasks C=1, periods consecutive near 1e12: 1e12-254 .. 1e12
	{
		var hp []periodicTask
		for i:=0;i<255;i++ {
			Tp := D-int64(254-i)
			hp = append(hp, periodicTask{priority:int64(i), execution:1, period:Tp, deadline:Tp})
		}
		cases = append(cases, tc{"consecutive-large", hp})
	}
	// 2) C=1, periods powers of 2
	{
		var hp []periodicTask
		for i:=0;i<40;i++ {
			Tp := int64(1)<<uint(i+1)
			hp = append(hp, periodicTask{priority:int64(i), execution:1, period:Tp, deadline:Tp})
		}
		cases = append(cases, tc{"powers-of-two", hp})
	}
	// 3) C=1 periods = consecutive 2..256 (U ~ 5ish >1 -> skip, force <1 via sparse)
	{
		var hp []periodicTask
		for i:=0;i<255;i++ {
			Tp := int64(257+i*3900000) // spread up to ~1e9, U tiny
			hp = append(hp, periodicTask{priority:int64(i), execution:1, period:Tp, deadline:Tp})
		}
		cases = append(cases, tc{"spread", hp})
	}
	// 4) near-saturation via many tasks: C=1, T=256..510 (the 68ms shape)
	{
		var hp []periodicTask
		for i:=0;i<255;i++ {
			Tp := int64(256+i)
			hp = append(hp, periodicTask{priority:int64(i), execution:1, period:Tp, deadline:Tp})
		}
		cases = append(cases, tc{"dense-small", hp})
	}

	for _, c := range cases {
		tk := periodicTask{priority:255, execution:1, period:D, deadline:D}
		var u big.Rat
		for _, h := range c.hp {
			u.Add(&u, new(big.Rat).SetFrac(big.NewInt(h.execution), big.NewInt(h.period)))
		}
		over := u.Cmp(big.NewRat(1,1)) >= 0
		k := roundsFor(tk, c.hp)
		fmt.Printf("%-18s hp=%3d U=%s rounds=%d over=%v\n", c.name, len(c.hp), new(big.Float).SetRat(&u).Text('f',6), k, over)
	}
}
