package server

import (
	"fmt"
	"math/rand"
	"testing"
)

// integer-only model of the accelerated iteration for round counting
func zzAccelRounds(C int64, hp [][2]int64, D int64) int {
	// U = num/den exact via float-free? use float64 ONLY for jump in this
	// search; round-count validation is integer exact below.
	var U float64
	for _, h := range hp {
		U += float64(h[0]) / float64(h[1])
	}
	if U >= 1.0 {
		return -1
	}
	w := C
	if j := int64(float64(C) / (1.0 - U)); j > w {
		if j > D {
			return 0
		}
		w = j
	}
	k := 0
	for {
		k++
		var G int64 = C
		for _, h := range hp {
			G += ((w + h[1] - 1) / h[1]) * h[0]
		}
		if G == w {
			return k
		}
		if G > D {
			return -k
		}
		w = G
	}
}

func TestZZFuzzRounds(t *testing.T) {
	rng := rand.New(rand.NewSource(99))
	gmax := 0
	var gw [2]int64
	var ghp [][2]int64
	randomTask := func() [2]int64 {
		// bias toward adversarial: large period, execution near period
		Tp := int64(1)
		switch rng.Intn(4) {
		case 0:
			Tp = int64(2 + rng.Intn(100000))
		case 1:
			Tp = int64(1 + rng.Int63n(1_000_000_000_000))
		case 2:
			Tp = []int64{1_000_000, 1_000_000_000, 1_000_000_000_000}[rng.Intn(3)]
		default:
			Tp = int64(2 + rng.Intn(1000))
		}
		var c int64
		switch rng.Intn(3) {
		case 0:
			c = Tp - int64(rng.Intn(4))
			if c < 1 {
				c = 1
			}
		case 1:
			c = 1 + rng.Int63n(Tp)
		default:
			c = 1 + rng.Int63n(min64(Tp, 1000))
		}
		return [2]int64{c, Tp}
	}
	for it := 0; it < 3_000_000; it++ {
		n := 1 + rng.Intn(8)
		hp := make([][2]int64, n)
		for i := range hp {
			hp[i] = randomTask()
		}
		C := int64(1 + rng.Intn(2000))
		D := int64(1_000_000_000_000)
		k := zzAccelRounds(C, hp, D)
		kk := k
		if kk < 0 {
			kk = -kk
		}
		if kk > gmax {
			gmax = kk
			gw = [2]int64{C, D}
			ghp = append([][2]int64(nil), hp...)
		}
	}
	fmt.Printf("MAX residual rounds over 3M configs: %d\nC=%v hp=%v\n", gmax, gw, ghp)
}

func min64(a, b int64) int64 {
	if a < b {
		return a
	}
	return b
}
