package server

import (
	"encoding/json"
	"math/big"
	"net/http"
)

const (
	periodicAnalyzePath = "/v1/schedules/periodic/analyze"
	maxPeriodicValue    = 1_000_000_000_000
	maxInt64            = 1<<63 - 1
)

type periodicTaskIn struct {
	ID        string `json:"id"`
	Priority  *int64 `json:"priority"`
	Execution *int64 `json:"execution"`
	Period    *int64 `json:"period"`
	Deadline  *int64 `json:"deadline"`
}

type periodicRequest struct {
	Tasks *[]periodicTaskIn `json:"tasks"`
}

type periodicTask struct {
	id        string
	priority  int64
	execution int64
	period    int64
	deadline  int64
}

type periodicTaskResult struct {
	ID             string `json:"id"`
	ResponseTime   *int64 `json:"responseTime"`
	DeadlineStatus string `json:"deadlineStatus"`
}

type periodicResponse struct {
	Schedulable bool                  `json:"schedulable"`
	Results     []periodicTaskResult `json:"results"`
}

func handlePeriodicAnalyze(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		w.Header().Set("Allow", http.MethodPost)
		writeAnalyzeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
		return
	}
	var req periodicRequest
	if !decodeStrictJSON(w, r, &req) {
		return
	}
	tasks, ok := validatePeriodicRequest(&req)
	if !ok {
		writeAnalyzeError(w, http.StatusUnprocessableEntity, "validation_failed")
		return
	}
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(http.StatusOK)
	_ = json.NewEncoder(w).Encode(analyzePeriodic(tasks))
}

func validatePeriodicRequest(req *periodicRequest) ([]periodicTask, bool) {
	if req.Tasks == nil || len(*req.Tasks) == 0 || len(*req.Tasks) > maxTasks {
		return nil, false
	}
	tasks := make([]periodicTask, 0, len(*req.Tasks))
	ids := make(map[string]struct{}, len(*req.Tasks))
	priorities := make(map[int64]struct{}, len(*req.Tasks))
	for i := range *req.Tasks {
		in := (*req.Tasks)[i]
		if !validTaskID(in.ID) {
			return nil, false
		}
		if _, dup := ids[in.ID]; dup {
			return nil, false
		}
		ids[in.ID] = struct{}{}
		if in.Priority == nil || *in.Priority < 0 || *in.Priority > 255 {
			return nil, false
		}
		if _, dup := priorities[*in.Priority]; dup {
			return nil, false
		}
		priorities[*in.Priority] = struct{}{}
		if in.Execution == nil || *in.Execution <= 0 || *in.Execution > maxPeriodicValue {
			return nil, false
		}
		if in.Period == nil || *in.Period <= 0 || *in.Period > maxPeriodicValue {
			return nil, false
		}
		if in.Deadline == nil || *in.Deadline <= 0 || *in.Deadline > maxPeriodicValue ||
			*in.Deadline > *in.Period {
			return nil, false
		}
		tasks = append(tasks, periodicTask{
			id:        in.ID,
			priority:  *in.Priority,
			execution: *in.Execution,
			period:    *in.Period,
			deadline:  *in.Deadline,
		})
	}
	return tasks, true
}

// analyzePeriodic computes worst-case response times under synchronous
// release, fixed priorities, preemptive scheduling, no blocking and no
// release jitter (constrained deadlines: deadline <= period).
func analyzePeriodic(tasks []periodicTask) periodicResponse {
	n := len(tasks)
	// hp[i] lists the strictly higher-priority tasks of task i in input
	// order; util[i] is their exact total utilization.
	hp := make([][]periodicTask, n)
	util := make([]*big.Rat, n)
	for i, t := range tasks {
		u := new(big.Rat)
		for j := range tasks {
			if tasks[j].priority < t.priority {
				hp[i] = append(hp[i], tasks[j])
				u.Add(u, new(big.Rat).SetFrac(
					big.NewInt(tasks[j].execution), big.NewInt(tasks[j].period)))
			}
		}
		util[i] = u
	}

	resp := periodicResponse{
		Schedulable: true,
		Results:     make([]periodicTaskResult, n),
	}
	for i, t := range tasks {
		rt := worstResponseTime(t, hp[i], util[i])
		result := periodicTaskResult{ID: t.id, ResponseTime: rt}
		if rt != nil && *rt <= t.deadline {
			result.DeadlineStatus = "met"
		} else {
			result.DeadlineStatus = "missed"
			resp.Schedulable = false
		}
		resp.Results[i] = result
	}
	return resp
}

// interference sums ceil(w/period)*execution over every higher-priority
// task. A result of false means the sum exceeds int64.
func interference(hp []periodicTask, w int64) (int64, bool) {
	var sum int64
	for _, t := range hp {
		jobs := (w + t.period - 1) / t.period
		term, ok := saturatingMul(jobs, t.execution)
		if !ok {
			return 0, false
		}
		sum, ok = saturatingAdd(sum, term)
		if !ok {
			return 0, false
		}
	}
	return sum, true
}

// worstResponseTime returns the least fixed point of
//
//	w = C + sum_j ceil(w/T_j) * C_j   (j ranging over hp)
//
// or nil if it does not settle at or before the deadline.
//
// Semantics and termination:
//
//   - With utilization U = sum C_j/T_j >= 1 there is no finite fixed point
//     (the higher-priority workload alone saturates the processor), so the
//     task misses immediately.
//   - With U < 1 the plain iteration from w0 = C is a strictly increasing
//     integer chain bounded by the least fixed point R; it reaches R or
//     crosses the deadline. Since ceil(w/T_j)*C_j >= (w/T_j)*C_j for every
//     w >= 0, g(w) >= C + U*w, hence R >= C/(1-U). Starting the monotone
//     iteration at floor(C/(1-U)) instead of C lands no later than R (a
//     non-decreasing g started below its least fixed point can never jump
//     past it) but skips the well-known pseudo-polynomial blow-up in which
//     tiny per-round increments walk all the way to a very distant fixed
//     point. The threshold and the jump use exact rational arithmetic, so a
//     boundary such as 1/3+1/3+1/3 == 1 is never misjudged by float rounding.
//   - The residual iteration after the jump is still, in the worst case,
//     pseudo-polynomial; values here are bounded by the 1e12 deadline and
//     stay inside int64 (saturating arithmetic is defense in depth).
func worstResponseTime(t periodicTask, hp []periodicTask, util *big.Rat) *int64 {
	if util.Cmp(big.NewRat(1, 1)) >= 0 || t.execution > t.deadline {
		return nil
	}
	// w0 = floor(C/(1-U)); 1-U = Num/Den, so this quotient is C*Den/Num.
	// The bound provably never exceeds the least fixed point.
	den := new(big.Rat).Sub(big.NewRat(1, 1), util)
	jump := new(big.Int).Quo(
		new(big.Int).Mul(big.NewInt(t.execution), den.Denom()), den.Num())
	if !jump.IsInt64() {
		return nil
	}
	w := t.execution
	if j := jump.Int64(); j > w {
		if j > t.deadline {
			return nil
		}
		w = j
	}

	for {
		f, ok := interference(hp, w)
		if !ok {
			return nil
		}
		next, ok := saturatingAdd(t.execution, f)
		if !ok || next > t.deadline {
			return nil
		}
		if next == w {
			rt := w
			return &rt
		}
		w = next
	}
}

func saturatingAdd(a, b int64) (int64, bool) {
	if b > maxInt64-a {
		return 0, false
	}
	return a + b, true
}

func saturatingMul(a, b int64) (int64, bool) {
	if a == 0 || b == 0 {
		return 0, true
	}
	if a > maxInt64/b {
		return 0, false
	}
	return a * b, true
}

