// worstResponseTime returns the least fixed point of
//
//	w = C + sum_j ceil(w/T_j) * C_j   (j ranging over hp)
//
// or nil if it does not settle at or before the deadline.
//
// Semantics and termination:
//
//   - If the higher-priority utilization U = sum C_j/T_j is at least 1 there
//     is no finite fixed point (those tasks alone saturate the processor), so
//     the task misses.
//   - Otherwise the standard iteration from w0 = C is a strictly increasing
//     integer chain up to the least fixed point R; it reaches R or crosses
//     the deadline. Starting above R would be wrong (g can have further,
//     larger fixed points even with U < 1), so every accelerated start must
//     be a proven lower bound of R. Since ceil(x/T_j)*C_j >= (x/T_j)*C_j,
//     g(x) >= C + U*x and therefore R >= C/(1-U); starting at
//     j0 = floor(C/(1-U)) skips the well-known pseudo-polynomial blow-up of
//     a distant fixed point while staying below R.
//
// Performance: the utilization sums and the candidate use float64, but U is
// re-judged with exact rational arithmetic inside a wide gray zone of 1 and
// j0 is confirmed with exact integer (128-bit) arithmetic, adjusting by at
// most a unit, so floating-point rounding can only shorten a jump, never
// change a verdict. The post-jump residual iteration remains, in the worst
// case, pseudo-polynomial.
func worstResponseTime(t periodicTask, hp []periodicTask, uf float64) *int64 {
	if t.execution > t.deadline {
		return nil
	}
	w := t.execitionSafe(hp, t.execution, w, t.deadline, uf)

	for {
		f, ok := interference(hp, w)
		if !ok {
			return nil
		}
		next, ok := saturatingAdd(t.execution, f)
		if !ok || next > t.deadline {
			return nil
		}
		if next == w {
			rt := w
			return &rt
		}
		w = next
	}
}

// jumpStart returns a proven lower bound on the least fixed point to start
// the iteration from, given the float utilization hint.
func jumpStart(hp []periodicTask, execution, deadline int64, uf float64) int64 {
	w := execution
	if uf >= 1.0-utilizationGrayZone {
		// Near or above saturation: classify and bound with exact arithmetic.
		u := exactUtilization(hp)
		if u.Cmp(big.NewRat(1, 1)) >= 0 {
			// Reported as > deadline so the caller treats it as a miss.
			return deadline + 1
		}
		d := new(big.Rat).Sub(big.NewRat(1, 1), u)
		j := new(big.Int).Quo(new(big.Int).Mul(big.NewInt(execution), d.Denom()), d.Num())
		if !j.IsInt64() {
			return deadline + 1
		}
		if jv := j.Int64(); jv > w {
			if jv > deadline {
				return deadline + 1
			}
			return jv
		}
		return w
	}

	jf := float64(execution) / (1.0-uf)
	if jf <= float64(w) {
		return w
	}
	if jf >= float64(maxInt64) {
		// Cannot be: U is well below 1 and bounded, but keep it exact anyway.
		u := exactUtilization(hp)
		d := new(big.Rat).Sub(big.NewRat(1, 1), u)
		j := new(big.Int).Quo(new(big.Int).Mul(big.NewInt(execution), d.Denom()), d.Num())
		if !j.IsInt64() || j.Int64() > deadline {
			return deadline + 1
		}
		if jv := j.Int64(); jv > w {
			return jv
		}
		return w
	}
	j := int64(jf)
	if j > deadline {
		j = deadline
	}
	// Correct float overshoot: linear-safe integers are exactly j <= j0, and
	// the hint differs from j0 by a sub-unit rounding.
	for j > w && !linearJumpSafe(hp, execution, j) {
		j--
	}
	if j > w {
		return j
	}
	return w
}

// linearJumpSafe reports exactly whether sum_j j*C_j/T_j <= j-execution,
// i.e. whether j <= C/(1-U), the linear lower bound on the fixed point.
// Products reach 1e24, so quotients use 128-bit division; the fractional
// part of the sum is accumulated as a float whose total error is below
// 1e-12, falling back to exact rational comparison only in the astronomically
// unlikely event that it sits next to an integer.
func linearJumpSafe(hp []periodicTask, execution, j int64) bool {
	budget := uint64(j - execution)
	var frac float64
	var rems, dens []int64
	for _, t := range hp {
		hi, lo := bits.Mul64(uint64(j), uint64(t.execution))
		if hi >= uint64(t.period) {
			// floor(j*C/T) alone exceeds the 64-bit budget.
			return false
		}
		q, rem := bits.Div64(hi, lo, uint64(t.period))
		if q > budget {
			return false
		}
		budget -= q
		if rem != 0 {
			frac += float64(rem) / float64(t.period)
			rems = append(rems, int64(rem))
			dens = append(dens, t.period)
		}
	}
	carry := int64(frac)
	rest := frac - float64(carry)
	if rest < 1e-9 || rest > 1.0-1e-9 {
		// Resolve the integer part of the fractional sum exactly.
		var sum big.Rat
		for k := range rems {
			sum.Add(&sum, new(big.Rat).SetFrac(big.NewInt(rems[k]), big.NewInt(dens[k])))
		}
		floor := new(big.Int).Quo(sum.Num(), sum.Denom())
		carry = floor.Int64()
	}
	return int64(carry) <= int64(budget)
}

// exactUtilization sums C_j/T_j exactly as a rational number.
func exactUtilization(hp []periodicTask) *big.Rat {
	u := new(big.Rat)
	for _, t := range hp {
		u.Add(u, new(big.Rat).SetFrac(big.NewInt(t.execution), big.NewInt(t.period)))
	}
	return u
}

