			deadline:  *in.Deadline,
		})
	}
	return tasks, true
}

// analyzePeriodic computes worst-case response times under synchronous
// release, fixed priorities, preemptive scheduling, no blocking and no
// release jitter (constrained deadlines: deadline <= period).
func analyzePeriodic(tasks []periodicTask) periodicResponse {
	n := len(tasks)
	// hp[i] lists the strictly higher-priority tasks of task i in input
	// order; util[i] is the (approximate, classification-only) utilization.
	hp := make([][]periodicTask, n)
	util := make([]float64, n)
	for i, t := range tasks {
		var u float64
		for j := range tasks {
			if tasks[j].priority < t.priority {
				hp[i] = append(hp[i], tasks[j])
				u += float64(tasks[j].execution) / float64(tasks[j].period)
			}
		}
		util[i] = u
	}

	resp := periodicResponse{
		Schedulable: true,
		Results:     make([]periodicTaskResult, n),
	}
	for i, t := range tasks {
		rt := worstResponseTime(t, hp[i], util[i])
		result := periodicTaskResult{ID: t.id, ResponseTime: rt}
		if rt != nil && *rt <= t.deadline {
			result.DeadlineStatus = "met"
		} else {
			result.DeadlineStatus = "missed"
			resp.Schedulable = false
		}
		resp.Results[i] = result
	}
	return resp
}

// interference sums ceil(w/period)*execution over every higher-priority
// task. A result of false means the sum exceeds int64.
func interference(hp []periodicTask, w int64) (int64, bool) {
	var sum int64
	for _, t := range hp {
		jobs := (w + t.period - 1) / t.period
		term, ok := saturatingMul(jobs, t.execution)
		if !ok {
			return 0, false
		}
		sum, ok = saturatingAdd(sum, term)
		if !ok {
			return 0, false
		}
	}
	return sum, true
}

// worstResponseTime returns the least fixed point of
//
//	w = C + sum_j ceil(w/T_j) * C_j   (j ranging over hp)
//
// or nil if it does not settle at or before the deadline.
//
// Semantics and termination:
//
//   - If the higher-priority utilization U = sum C_j/T_j is at least 1 there
//     is no finite fixed point (those tasks alone saturate the processor), so
//     the task misses.
//   - Otherwise the iteration from w0 = C is a strictly increasing integer
//     chain bounded by the least fixed point R; it reaches R or crosses the
//     deadline. Because ceil(w/T_j)*C_j >= (w/T_j)*C_j for every w >= 0,
//     g(w) >= C + U*w, hence R >= C/(1-U). Starting at floor(C/(1-U)) lands
//     no later than R (a non-decreasing g started below its least fixed
//     point cannot jump past it) but skips the well-known pseudo-polynomial
//     blow-up of a distant fixed point.
//
// Performance: the utilization sum and the jump candidate are cheap float64
// values used only for classification and as a hint. Every hint is confirmed
// with exact integer (128-bit) arithmetic before use, and inputs whose float
// utilization lies within a wide gray zone of 1 fall back to exact rational
// arithmetic; float rounding therefore can never change a verdict. The
// post-jump residual iteration is, in the worst case, pseudo-polynomial.
func worstResponseTime(t periodicTask, hp []periodicTask, uf float64) *int64 {
	if t.execution > t.deadline {
		return nil
	}
	w := t.execution

	if uf >= 1.0-utilizationGrayZone {
		// Near or above the boundary: decide and jump with exact arithmetic.
		ru := exactUtilization(hp)
		one := big.NewRat(1, 1)
		if ru.Cmp(one) >= 0 {
			return nil
		}
		if j := exactJumpFloor(t.execution, ru); j > w {
			if j > t.deadline {
				return nil
			}
			w = j
		}
	} else if jf := float64(t.execution) / (1.0 - uf); jf > float64(w) {
		// U is certainly below 1. The float value is only a hint: it is
		// capped to the deadline and every candidate is confirmed with exact
		// integer arithmetic before use, so rounding can at worst shorten the
		// jump, never change the verdict.
		var j int64
		if jf >= float64(maxInt64) {
			j = t.deadline
		} else {
			j = int64(jf)
			if j > t.deadline {
				j = t.deadline
			}
		}
		for j > w && !jumpIsSafe(hp, t.execution, j) {
			j--
		}
		if j > w {
			w = j
		}
	}

	for {
		f, ok := interference(hp, w)
		if !ok {
			return nil
		}
		next, ok := saturatingAdd(t.execution, f)
		if !ok || next > t.deadline {
			return nil
		}
		if next == w {
			rt := w
			return &rt
		}
		w = next
	}
}

// jumpIsSafe reports exactly whether C + sum_j ceil(j/T_j)*C_j <= j, i.e.
// whether j is no greater than the least fixed point. Products reach 1e24
// (above 64 bits), so each ceil is evaluated in 128-bit arithmetic.
func jumpIsSafe(hp []periodicTask, execution, j int64) bool {
	budget := uint64(j - execution)
	for _, t := range hp {
		hi, lo := bits.Mul64(uint64(t.execution), uint64(j))
		if hi >= uint64(t.period) {
			// The quotient does not fit in 64 bits, hence exceeds budget.
			return false
		}
		q, rem := bits.Div64(hi, lo, uint64(t.period))
		if rem != 0 {
			if q == ^uint64(0) {
				return false
			}
			q++
		}
		if q > budget {
			return false
		}
		budget -= q
	}
	return true
}

// exactUtilization sums C_j/T_j exactly as a rational number.
func exactUtilization(hp []periodicTask) *big.Rat {
	u := new(big.Rat)
	for _, t := range hp {
		u.Add(u, new(big.Rat).SetFrac(big.NewInt(t.execution), big.NewInt(t.period)))
	}
	return u
}

// exactJumpFloor returns floor(C/(1-U)); a value above the deadline is
// clamped to deadline+1 since the caller only needs that comparison.
func exactJumpFloor(execution int64, u *big.Rat) int64 {
	den := new(big.Rat).Sub(big.NewRat(1, 1), u)
	j := new(big.Int).Quo(
		new(big.Int).Mul(big.NewInt(execution), den.Denom()), den.Num())
	if !j.IsInt64() {
		return maxPeriodicValue + 1
	}
	return j.Int64()
}

func saturatingAdd(a, b int64) (int64, bool) {
	if b > maxInt64-a {
		return 0, false
	}
	return a + b, true
}

func saturatingMul(a, b int64) (int64, bool) {
	if a == 0 || b == 0 {
		return 0, true
	}
	if a > maxInt64/b {
		return 0, false
	}
	return a * b, true
}

