package server

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"strconv"
	"strings"
	"testing"
	"time"
)

func TestZZHTTP256(t *testing.T) {
	build := func(kind int) string {
		var b strings.Builder
		b.WriteString(`{"tasks":[`)
		for i := 0; i < 256; i++ {
			if i > 0 { b.WriteByte(',') }
			if i == 0 {
				b.WriteString(periodicTaskObj("low", 255, 1, 1000000000000, 1000000000000))
			} else {
				var T int64
				switch kind {
				case 0:
					T = int64(255 + i)
				case 1:
					T = 1 << uint(i%40+1) // geometric-ish, unique needed -> vary
				default:
					T = int64(10_000_000 + i*3_900_000_000)
				}
				b.WriteString(periodicTaskObj("h"+strconv.Itoa(i), int64(i-1), 1, T, T))
			}
		}
		b.WriteString(`]}`)
		return b.String()
	}
	for kind := 0; kind < 3; kind++ {
		body := build(kind)
		var best time.Duration = 1<<62
		for k := 0; k < 30; k++ {
			rec := httptest.NewRecorder()
			r := httptest.NewRequest(http.MethodPost, periodicAnalyzePath, strings.NewReader(body))
			r.Header.Set("Content-Type", "application/json")
			st := time.Now()
			Handler().ServeHTTP(rec, r)
			if d := time.Since(st); d < best { best = d }
			if rec.Code != 200 { t.Fatalf("kind %d status %d %s", kind, rec.Code, rec.Body.String()) }
		}
		fmt.Printf("kind %d best per request: %v\n", kind, best)
	}
}
EOF
