	"net/http/httptest"
	"strconv"
	"strings"
	"testing"
	"time"
)

func TestZZHTTP256(t *testing.T) {
	build := func(kind int) string {
		var b strings.Builder
		b.WriteString(`{"tasks":[`)
		for i := 0; i < 256; i++ {
			if i > 0 { b.WriteByte(',') }
			if i == 0 {
				b.WriteString(periodicTaskObj("low", 255, 1, 1000000000000, 1000000000000))
			} else {
				var T int64
				switch kind {
				case 0:
					T = int64(255 + i) // dense small, U~0.69
				case 1:
					T = int64(10_000_000 + i*3_900_000_000) // sparse, tiny U
				default:
					T = 1 << uint(39 - i%10) // powers, all <=2^39 < 1e12
				}
				b.WriteString(periodicTaskObj("h"+strconv.Itoa(i), int64(i-1), 1, T, T))
			}
		}
		b.WriteString(`]}`)
		return b.String()
	}
	for kind := 0; kind < 3; kind++ {
		body := build(kind)
		var best time.Duration = 1 << 62
		for k := 0; k < 30; k++ {
			rec := httptest.NewRecorder()
			r := httptest.NewRequest(http.MethodPost, periodicAnalyzePath, strings.NewReader(body))
