func saturatingAdd(a, b int64) (int64, bool) {
	if b > maxInt64-a {
		return 0, false
	}
	return a + b, true
}

func saturatingMul(a, b int64) (int64, bool) {
	if a == 0 || b == 0 {
		return 0, true
	}
	if a > maxInt64/b {
		return 0, false
	}
	return a * b, true
}

